mapper.select:
SELECT DISTINCT s.* FROM students s
INNER JOIN students_courses sc ON sc.student_id = s.id AND sc.deleted = 0 LEFT JOIN students_course_status st ON st.student_course_id = sc.student_course_id AND st.deleted = 0
s.deleted = 0
AND s.name LIKE CONCAT('%', #{name}, '%')
AND s.gender = #{gender}
AND sc.course_id = #{courseId}
AND st.status = #{status}
AND s.age <= 19
AND s.age >= 20 AND s.age <= 29
AND s.age >= 30 AND s.age <= 39

SELECT sc.student_course_id AS id, sc.student_id AS studentId, sc.course_id AS courseId, sc.course_name AS courseName, sc.course_start_at AS courseStartAt, sc.course_end_at AS courseEndAt, sc.deleted AS deleted, st.status AS courseStatus FROM students_courses sc
LEFT JOIN students_course_status st ON st.student_course_id = sc.student_course_id AND st.deleted = 0
WHERE sc.deleted = 0
AND sc.course_id = #{courseId}
AND st.status = #{status}

SELECT student_course_id
FROM students_courses
WHERE student_id = #{studentId}
AND course_id = #{courseId}
AND deleted = 0

